// Tasa efectiva para importadoras = VRD (BCB diario) + spread bancario.
// Dato del dueno de BE: los bancos agregan ~0.10 Bs sobre el VRD y NO
// aceptan fondos via Binance -> Binance es solo referencia.
// Ver onia-core/ONIA_EXCHANGE_RATE_AUTOPRICING_2026.md
const OFICIAL_COMPRA = 6.86;
const OFICIAL_VENTA = 6.96;
const SPREAD_BANCARIO = 0.10; // config por organizacion en v2

let paralelo = null;
try {
  const data = $('Binance P2P USDT/BOB').first().json;
  const prices = (data.data || [])
    .map((row) => Number(row?.adv?.price))
    .filter((price) => Number.isFinite(price) && price > 0)
    .sort((a, b) => a - b);
  if (prices.length) {
    paralelo = prices[Math.floor(prices.length / 2)];
  }
} catch (error) { /* sin datos binance */ }

let vrd = null;
try {
  const html = String($('BCB home (VRD)').first().json.data ?? $('BCB home (VRD)').first().json ?? '');
  const match = html.match(/VRD[^0-9]{0,80}([0-9]{1,2}[.,][0-9]{2})/i) || html.match(/[Rr]eferencial[^0-9]{0,80}([0-9]{1,2}[.,][0-9]{2})/);
  if (match) vrd = Number(match[1].replace(',', '.'));
} catch (error) { /* BCB no disponible */ }

const efectiva = vrd ? vrd + SPREAD_BANCARIO : null;
const fecha = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz', day: '2-digit', month: '2-digit', year: 'numeric' });

const lineas = [
  `Tipo de cambio Bolivia — ${fecha}`,
  ``,
  vrd ? `VRD (BCB): ${vrd.toFixed(2)} Bs` : `VRD: no disponible hoy (revisar scraper)`,
  efectiva ? `TASA EFECTIVA (VRD + ${SPREAD_BANCARIO.toFixed(2)} banco): ${efectiva.toFixed(2)} Bs  <- esta mueve precios` : null,
  paralelo ? `Referencia Binance P2P: ${paralelo.toFixed(2)} Bs (no usable via bancos)` : `Referencia Binance: no disponible`,
  `Oficial fijo: ${OFICIAL_COMPRA} / ${OFICIAL_VENTA} (solo factura/SIAT)`,
  ``,
  `Cambio de tasa => repreciar con aprobacion del dueno (nunca automatico).`,
].filter((line) => line !== null);

return [{ json: { text: lineas.join('\n'), oficialVenta: OFICIAL_VENTA, vrd, spreadBancario: SPREAD_BANCARIO, tasaEfectiva: efectiva, referenciBinance: paralelo } }];
